class Solution {
    public boolean isValidSudoku(char[][] board) {
        Set<Character>[] rows = new HashSet[9];
        Set<Character>[] cols = new HashSet[9];
        Set<Character>[] boxes = new HashSet[9];

        for (int i = 0; i < 9; i++) {
            rows[i] = new HashSet<>();
            cols[i] = new HashSet<>();
            boxes[i] = new HashSet<>();
        }

        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                char val = board[r][c];
                if (val == '.') continue;

                int boxIdx = (r / 3) * 3 + (c / 3);

                if (rows[r].contains(val) || 
                    cols[c].contains(val) || 
                    boxes[boxIdx].contains(val)) {
                    return false;
                }

                rows[r].add(val);
                cols[c].add(val);
                boxes[boxIdx].add(val);
            }
        }

        return true;
    }
}

class Solution {
    public boolean isValidSudoku(char[][] board) {
        Set<String> seen = new HashSet<>();

        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                char val = board[r][c];
                if (val == '.') continue;

                int boxIdx = (r / 3) * 3 + (c / 3);

                String rowKey = "row" + r + val;
                String colKey = "col" + c + val;
                String boxKey = "box" + boxIdx + val;

                if (seen.contains(rowKey) || 
                    seen.contains(colKey) || 
                    seen.contains(boxKey)) {
                    return false;
                }

                seen.add(rowKey);
                seen.add(colKey);
                seen.add(boxKey);
            }
        }

        return true;
    }
}

class Solution {
    public boolean isValidSudoku(char[][] board) {
        int[] rows = new int[9];
        int[] cols = new int[9];
        int[] boxes = new int[9];

        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                char val = board[r][c];
                if (val == '.') continue;

                int digit = val - '0';
                int mask = 1 << digit;
                int boxIdx = (r / 3) * 3 + (c / 3);

                if ((rows[r] & mask) != 0 || 
                    (cols[c] & mask) != 0 || 
                    (boxes[boxIdx] & mask) != 0) {
                    return false;
                }

                rows[r] |= mask;
                cols[c] |= mask;
                boxes[boxIdx] |= mask;
            }
        }

        return true;
    }
}
